inputSchema:
{
  "type": "object",
  "properties": {
    "code": {
      "type": "string",
      "description": "The JavaScript source code to lint",
      "minLength": 1
    },
    "strict": {
      "type": "boolean",
      "description": "Enable stricter rules (no-console, eqeqeq as errors)"
    }
  },
  "required": [
    "code"
  ]
}

func:
const { Linter } = eslint;
const linter = new Linter();

const strict = msg.payload.strict === true;

const results = linter.verify(msg.payload.code, {
    languageOptions: { ecmaVersion: 2022, sourceType: "script" },
    rules: {
        "no-undef": "off",
        "no-unused-vars": "off", 
        "no-redeclare": "error",
        "no-dupe-keys": "error",
        "no-unreachable": "error",
        "eqeqeq": strict ? "error" : "warn",
        "no-console": strict ? "error" : "off",
        "semi": "warn"
    }
});

msg.payload = {
    problemCount: results.length,
    errors: results.filter(r => r.severity === 2).length,
    warnings: results.filter(r => r.severity === 1).length,
    problems: results.map(r => ({
        line: r.line,
        column: r.column,
        severity: r.severity === 2 ? "error" : "warning",
        rule: r.ruleId,
        message: r.message
    }))
};
return msg;

var config = { retries: 3, timeout: 500, mode: "fast" };

function checkTemp(reading) {
    if (reading === null) {
        return false;
    }
    return reading > 75;
}

const nodes = JSON.parse(msg.payload.flow);
const issues = [];

const hasCatch = nodes.some(n => n.type === "catch");
if (!hasCatch) {
    issues.push({
        severity: "warning", rule: "missing-catch",
        message: "Flow has no Catch node. Errors will go unhandled."
    });
}

for (const n of nodes) {
    if (n.type === "function") {
        if (!n.name) {
            issues.push({
                severity: "warning", rule: "unnamed-function",
                node: n.id, message: "Function node has no name."
            });
        }
        if (n.func && /(password|apikey|api_key|secret|token)\s*[:=]\s*["'][^"']+["']/i.test(n.func)) {
            issues.push({
                severity: "error", rule: "hardcoded-credential",
                node: n.id, name: n.name || "(unnamed)",
                message: "Possible hardcoded credential in Function code. Use environment variables."
            });
        }
    }
}

msg.payload = { valid: issues.filter(i => i.severity === "error").length === 0, issues };
return msg;
